1	package org.springframework.samples.petclinic.mapper;
2	
3	import org.jspecify.annotations.NonNull;
4	import org.jspecify.annotations.Nullable;
5	import org.mapstruct.Mapper;
6	import org.mapstruct.Mapping;
7	import org.springframework.data.domain.Page;
8	import org.springframework.samples.petclinic.model.Owner;
9	import org.springframework.samples.petclinic.rest.dto.OwnerDto;
10	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
11	import org.springframework.samples.petclinic.rest.dto.OwnerPageDto;
12	
13	import java.util.Collection;
14	import java.util.List;
15	
16	/**
17	 * Maps Owner & OwnerDto using Mapstruct
18	 */
19	@Mapper(uses = PetMapper.class)
20	public interface OwnerMapper {
21	
22	    @Mapping(target = "salutation", expression = "java(salutation(owner))")
23	    @Mapping(target = "displayName", expression = "java(displayName(owner))")
24	    @Mapping(target = "initials", expression = "java(initials(owner))")
25	    @Mapping(target = "telephoneDisplay", expression = "java(telephoneDisplay(owner))")
26	    @Mapping(target = "membershipNumber", expression = "java(membershipNumber(owner))")
27	    @Mapping(target = "checkDigit", expression = "java(checkDigit(owner))")
28	    @Mapping(target = "membershipPoints", expression = "java(membershipPoints(owner))")
29	    @Mapping(target = "membershipLevel", expression = "java(membershipLevel(owner))")
30	    @Mapping(target = "locality", expression = "java(locality(owner))")
31	    @Mapping(target = "timezone", expression = "java(timezone(owner))")
32	    @Mapping(target = "contactPreference", expression = "java(contactPreference(owner))")
33	    @Mapping(target = "identityKey", expression = "java(identityKey(owner))")
34	    @Mapping(target = "ageBand", expression = "java(ageBand(owner))")
35	    @Mapping(target = "fiscalYear", expression = "java(fiscalYear(owner))")
36	    @Mapping(target = "selfLink", expression = "java(selfLink(owner))")
37	    @Mapping(target = "ownerSegment", expression = "java(ownerSegment(owner))")
38	    OwnerDto toOwnerDto(Owner owner);
39	
40	    /**
41	     * Derives the owner's {@code ownerSegment}, formatted {@code '<TIER>_<AREA>'}. TIER is
42	     * {@code PREMIUM} when membershipLevel is 3 or more, otherwise {@code STANDARD}. AREA is
43	     * {@code METRO} when the locality is a known region ({@code NSW}, {@code VIC} or {@code QLD}),
44	     * otherwise {@code REGIONAL}. Returns {@code null} when the owner is absent.
45	     */
46	    default OwnerDto.@Nullable OwnerSegmentEnum ownerSegment(@Nullable Owner owner) {
47	        if (owner == null) {
48	            return null;
49	        }
50	        Integer level = membershipLevel(owner);
51	        boolean premium = level != null && level >= 3;
52	        String region = locality(owner);
53	        boolean metro = "NSW".equals(region) || "VIC".equals(region) || "QLD".equals(region);
54	        String tier = premium ? "PREMIUM" : "STANDARD";
55	        String area = metro ? "METRO" : "REGIONAL";
56	        return OwnerDto.OwnerSegmentEnum.fromValue(tier + "_" + area);
57	    }
58	
59	    /**
60	     * Derives the owner's {@code selfLink}, the canonical relative URL of the owner formatted as
61	     * {@code '/api/owners/' + id}. Returns {@code null} when the owner or its id is absent.
62	     */
63	    default @Nullable String selfLink(@Nullable Owner owner) {
64	        if (owner == null || owner.getId() == null) {
65	            return null;
66	        }
67	        return "/api/owners/" + owner.getId();
68	    }
69	
70	    /**
71	     * The fiscal year in which a date falls, labelled by the calendar year in which the fiscal year
72	     * ends. The fiscal year starts on 1 July, so a date on or after 1 July belongs to the fiscal year
73	     * ending the following calendar year, and a date before 1 July belongs to the fiscal year ending
74	     * that calendar year.
75	     */
76	    private static int fiscalYearEnding(java.time.LocalDate date) {
77	        return date.getMonthValue() >= java.time.Month.JULY.getValue() ? date.getYear() + 1 : date.getYear();
78	    }
79	
80	    /**
81	     * Derives the owner's {@code fiscalYear} from its business-day-adjusted registrationDate, formatted
82	     * as {@code 'FY<YY>'} where YY is the last two digits of the calendar year in which the fiscal year
83	     * ends (the fiscal year starts on 1 July). Returns {@code null} when the owner has no
84	     * registrationDate.
85	     */
86	    default @Nullable String fiscalYear(@Nullable Owner owner) {
87	        if (owner == null || owner.getRegistrationDate() == null) {
88	            return null;
89	        }
90	        return String.format("FY%02d", fiscalYearEnding(owner.getRegistrationDate()) % 100);
91	    }
92	
93	    /**
94	     * Derives the owner's {@code ageBand} from its birthDate relative to the registrationDate:
95	     * {@code MINOR} when under 18, {@code ADULT} when 18 to 64, and {@code SENIOR} when 65 or older.
96	     * Returns {@code null} when the owner has no birthDate or no registrationDate.
97	     */
98	    default OwnerDto.@Nullable AgeBandEnum ageBand(@Nullable Owner owner) {
99	        if (owner == null || owner.getBirthDate() == null || owner.getRegistrationDate() == null) {
100	            return null;
101	        }
102	        int age = java.time.Period.between(owner.getBirthDate(), owner.getRegistrationDate()).getYears();
103	        if (age < 18) {
104	            return OwnerDto.AgeBandEnum.MINOR;
105	        }
106	        if (age < 65) {
107	            return OwnerDto.AgeBandEnum.ADULT;
108	        }
109	        return OwnerDto.AgeBandEnum.SENIOR;
110	    }
111	
112	    /**
113	     * Derives the owner's duplicate-detection {@code identityKey}: the lower-case hex SHA-256 of
114	     * {@code normalizedTelephone + '|' + lowerEmail + '|' + soundex(lastName)}, with an empty segment
115	     * for an absent telephone or email. This is the same key the create endpoint uses to reject an
116	     * owner whose whole key equals an existing owner's.
117	     */
118	    default @Nullable String identityKey(@Nullable Owner owner) {
119	        if (owner == null) {
120	            return null;
121	        }
122	        return org.springframework.samples.petclinic.util.IdentityKeys.identityKey(
123	            owner.getTelephone(), owner.getEmail(), owner.getLastName());
124	    }
125	
126	    /**
127	     * Derives the owner's preferred contact channel: {@code EMAIL} when an email is present,
128	     * otherwise {@code PHONE}.
129	     */
130	    default OwnerDto.@Nullable ContactPreferenceEnum contactPreference(@Nullable Owner owner) {
131	        if (owner == null) {
132	            return null;
133	        }
134	        boolean hasEmail = owner.getEmail() != null && !owner.getEmail().isEmpty();
135	        return hasEmail ? OwnerDto.ContactPreferenceEnum.EMAIL : OwnerDto.ContactPreferenceEnum.PHONE;
136	    }
137	
138	    /**
139	     * Derives the owner's locality from its region-and-hash identity: the {@code REGION} prefix of
140	     * the {@code customerCode} ({@code '<REGION>-<HASH8>'}), which is the region code derived from
141	     * the postcode on create. Returns the canonical region string, or {@code 'UNKNOWN'} when the
142	     * owner has no customerCode.
143	     */
144	    default @Nullable String locality(@Nullable Owner owner) {
145	        if (owner == null) {
146	            return null;
147	        }
148	        String customerCode = owner.getCustomerCode();
149	        if (customerCode == null) {
150	            return "UNKNOWN";
151	        }
152	        int dash = customerCode.indexOf('-');
153	        return dash < 0 ? "UNKNOWN" : customerCode.substring(0, dash);
154	    }
155	
156	    /**
157	     * Derives the owner's {@code timezone} as an IANA name from its locality/region using the fixed
158	     * region-to-timezone table: {@code NSW -> Australia/Sydney}, {@code VIC -> Australia/Melbourne},
159	     * and {@code QLD -> Australia/Brisbane}. Returns {@code null} when the region is not in the table.
160	     */
161	    default @Nullable String timezone(@Nullable Owner owner) {
162	        String region = locality(owner);
163	        if (region == null) {
164	            return null;
165	        }
166	        return switch (region) {
167	            case "NSW" -> "Australia/Sydney";
168	            case "VIC" -> "Australia/Melbourne";
169	            case "QLD" -> "Australia/Brisbane";
170	            default -> null;
171	        };
172	    }
173	
174	    /**
175	     * Returns the owner's membership points. Starting at 0, it adds 2 when an email is present, 1
176	     * when namesakeCount is 0, 2 when the owner belongs to a household of at least 3 members, and 3
177	     * when tenure spans at least one elapsed fiscal year since the registrationDate (the fiscal year
178	     * starts on 1 July). Because a newly created owner shares the current fiscal year it never earns
179	     * the tenure points.
180	     */
181	    default @Nullable Integer membershipPoints(@Nullable Owner owner) {
182	        if (owner == null) {
183	            return null;
184	        }
185	        int points = 0;
186	        boolean hasEmail = owner.getEmail() != null && !owner.getEmail().isEmpty();
187	        if (hasEmail) {
188	            points += 2;
189	        }
190	        boolean noNamesakes = owner.getNamesakeCount() != null && owner.getNamesakeCount() == 0;
191	        if (noNamesakes) {
192	            points += 1;
193	        }
194	        boolean largeHousehold = owner.getHouseholdSize() != null && owner.getHouseholdSize() >= 3;
195	        if (largeHousehold) {
196	            points += 2;
197	        }
198	        if (hasQualifyingTenure(owner)) {
199	            points += 3;
200	        }
201	        return points;
202	    }
203	
204	    /**
205	     * Returns the owner's numeric membership level. When a membership level has been persisted on the
206	     * owner (the household-capped value assigned on create) that stored value is returned; otherwise the
207	     * level is derived from membershipPoints via {@link #derivedMembershipLevel(Owner)}.
208	     */
209	    default @Nullable Integer membershipLevel(@Nullable Owner owner) {
210	        if (owner != null && owner.getMembershipLevel() != null) {
211	            return owner.getMembershipLevel();
212	        }
213	        return derivedMembershipLevel(owner);
214	    }
215	
216	    /**
217	     * Derives the owner's numeric membership level from 1 to 4 from membershipPoints, ignoring any
218	     * stored value: level 1 for 0-1 points, 2 for 2-3, 3 for 4-5, and 4 for 6 or more points.
219	     */
220	    default @Nullable Integer derivedMembershipLevel(@Nullable Owner owner) {
221	        Integer points = membershipPoints(owner);
222	        if (points == null) {
223	            return null;
224	        }
225	        if (points <= 1) {
226	            return 1;
227	        }
228	        if (points <= 3) {
229	            return 2;
230	        }
231	        if (points <= 5) {
232	            return 3;
233	        }
234	        return 4;
235	    }
236	
237	    /**
238	     * Whether the owner's tenure spans at least one elapsed fiscal year, i.e. the current fiscal year
239	     * is later than the fiscal year of its registrationDate (the fiscal year starts on 1 July).
240	     * Returns {@code false} when the registrationDate is absent (or in the future, which shares the
241	     * current fiscal year), so a newly created owner has no qualifying tenure.
242	     */
243	    default boolean hasQualifyingTenure(@Nullable Owner owner) {
244	        if (owner == null || owner.getRegistrationDate() == null) {
245	            return false;
246	        }
247	        int elapsedFiscalYears = fiscalYearEnding(java.time.LocalDate.now())
248	            - fiscalYearEnding(owner.getRegistrationDate());
249	        return elapsedFiscalYears >= 1;
250	    }
251	
252	    /**
253	     * Formats an owner's membership number as {@code '<customerCode>-M<YY>'}, where YY is the last two
254	     * digits of the fiscal year (ending) derived from the business-day-adjusted registrationDate, e.g.
255	     * {@code 'MEL-SMI-0007-M26'}.
256	     */
257	    default @Nullable String membershipNumber(@Nullable Owner owner) {
258	        if (owner == null || owner.getCustomerCode() == null || owner.getRegistrationDate() == null) {
259	            return null;
260	        }
261	        return String.format("%s-M%02d", owner.getCustomerCode(), fiscalYearEnding(owner.getRegistrationDate()) % 100);
262	    }
263	
264	    /**
265	     * Returns the Luhn check digit (0-9) computed over the digits contained in the owner's
266	     * customerCode, or {@code null} when the owner or its customerCode is absent.
267	     */
268	    default @Nullable Integer checkDigit(@Nullable Owner owner) {
269	        if (owner == null || owner.getCustomerCode() == null) {
270	            return null;
271	        }
272	        String s = owner.getCustomerCode();
273	        int sum = 0;
274	        boolean dbl = true;
275	        for (int i = s.length() - 1; i >= 0; i--) {
276	            char c = s.charAt(i);
277	            if (c < '0' || c > '9') {
278	                continue;
279	            }
280	            int d = c - '0';
281	            if (dbl) {
282	                d *= 2;
283	                if (d > 9) {
284	                    d -= 9;
285	                }
286	            }
287	            sum += d;
288	            dbl = !dbl;
289	        }
290	        return (10 - (sum % 10)) % 10;
291	    }
292	
293	    /**
294	     * Formats the owner's stored E.164 {@code telephone} for humans: the country code, a space, then
295	     * the national digits grouped in threes separated by spaces, e.g. {@code '+61 412 345 678'} for a
296	     * stored {@code '+61412345678'}. The country code is the single digit for the {@code +1} and
297	     * {@code +7} plans and two digits otherwise. Returns the raw value unchanged when it is not a
298	     * {@code '+'}-prefixed digit string, or {@code null} when absent.
299	     */
300	    default @Nullable String telephoneDisplay(@Nullable Owner owner) {
301	        if (owner == null) {
302	            return null;
303	        }
304	        String telephone = owner.getTelephone();
305	        if (telephone == null || !telephone.matches("\\+\\d+")) {
306	            return telephone;
307	        }
308	        String digits = telephone.substring(1);
309	        int countryCodeLength = (digits.startsWith("1") || digits.startsWith("7")) ? 1 : 2;
310	        countryCodeLength = Math.min(countryCodeLength, digits.length());
311	        String countryCode = digits.substring(0, countryCodeLength);
312	        String national = digits.substring(countryCodeLength);
313	        StringBuilder sb = new StringBuilder("+").append(countryCode);
314	        for (int i = 0; i < national.length(); i += 3) {
315	            sb.append(' ').append(national, i, Math.min(i + 3, national.length()));
316	        }
317	        return sb.toString();
318	    }
319	
320	    /**
321	     * Composes the owner's salutation as {@code 'title lastName'} when a title is present,
322	     * or just the {@code lastName} when no title is given.
323	     */
324	    default @Nullable String salutation(@Nullable Owner owner) {
325	        if (owner == null) {
326	            return null;
327	        }
328	        String title = owner.getTitle();
329	        if (title == null || title.isEmpty()) {
330	            return owner.getLastName();
331	        }
332	        return title + " " + owner.getLastName();
333	    }
334	
335	    /**
336	     * Formats an owner's stored names as {@code 'LastName, FirstName'}.
337	     */
338	    default @Nullable String displayName(@Nullable Owner owner) {
339	        if (owner == null) {
340	            return null;
341	        }
342	        return owner.getLastName() + ", " + owner.getFirstName();
343	    }
344	
345	    /**
346	     * Formats an owner's initials as the upper-cased first letters of firstName and
347	     * lastName, dot-separated with a trailing dot, e.g. {@code 'J.S.'}.
348	     */
349	    default @Nullable String initials(@Nullable Owner owner) {
350	        if (owner == null) {
351	            return null;
352	        }
353	        StringBuilder sb = new StringBuilder();
354	        String firstName = owner.getFirstName();
355	        if (firstName != null && !firstName.isEmpty()) {
356	            sb.append(Character.toUpperCase(firstName.charAt(0))).append('.');
357	        }
358	        String lastName = owner.getLastName();
359	        if (lastName != null && !lastName.isEmpty()) {
360	            sb.append(Character.toUpperCase(lastName.charAt(0))).append('.');
361	        }
362	        return sb.toString();
363	    }
