17	package org.springframework.samples.petclinic.util;
18	
19	import java.nio.charset.StandardCharsets;
20	import java.security.MessageDigest;
21	import java.security.NoSuchAlgorithmException;
22	
23	/**
24	 * Derivation of an owner's duplicate-detection {@code identityKey}. The key is the lower-case hex
25	 * SHA-256 of {@code normalizedTelephone + '|' + lowerEmail + '|' + soundex(lastName)}, with an empty
26	 * segment substituted for an absent telephone or email. Because a Soundex code (not the raw surname)
27	 * and the telephone both feed the key, two owners collide only when their telephone, email and the
28	 * phonetic code of their surname all match; owners that differ in any one of those segments — for
29	 * example two members of the same household with different telephones — produce different keys.
30	 *
31	 * <p>Both the create endpoint (for its single duplicate check) and the owner mapper (which exposes
32	 * the key on the DTO) derive the key here, so the value a caller sees is exactly the value the
33	 * server compares against.
34	 */
35	public final class IdentityKeys {
36	
37	    private IdentityKeys() {
38	    }
39	
40	    /**
41	     * Derives the {@code identityKey} from an owner's already-normalized telephone and email and its
42	     * raw last name (which is reduced to its Soundex code here).
43	     *
44	     * @param normalizedTelephone the E.164 telephone, or {@code null}
45	     * @param lowerEmail the lower-cased email, or {@code null}
46	     * @param lastName the last name, or {@code null}
47	     * @return the 64-character lower-case hex identity key
48	     */
49	    public static String identityKey(String normalizedTelephone, String lowerEmail, String lastName) {
50	        String raw = (normalizedTelephone == null ? "" : normalizedTelephone)
51	            + "|" + (lowerEmail == null ? "" : lowerEmail)
52	            + "|" + soundex(lastName);
53	        return sha256Hex(raw);
54	    }
55	
56	    /**
57	     * The American Soundex phonetic code of {@code name}: its first letter followed by three digits
58	     * encoding the remaining consonants, upper-cased and padded/truncated to four characters. Letters
59	     * that share an encoding stay a single digit when adjacent or separated only by {@code h}/{@code w};
60	     * a vowel between them re-encodes the digit. Non-letters are ignored; an empty or letter-free name
61	     * yields the empty string.
62	     *
63	     * @param name the name to encode, may be {@code null}
64	     * @return the Soundex code, or the empty string when the name has no letters
65	     */
66	    public static String soundex(String name) {
67	        if (name == null) {
68	            return "";
69	        }
70	        StringBuilder letters = new StringBuilder();
71	        for (int i = 0; i < name.length(); i++) {
72	            char c = Character.toUpperCase(name.charAt(i));
73	            if (c >= 'A' && c <= 'Z') {
74	                letters.append(c);
75	            }
76	        }
77	        if (letters.length() == 0) {
78	            return "";
79	        }
80	        StringBuilder code = new StringBuilder();
81	        code.append(letters.charAt(0));
82	        char previous = digit(letters.charAt(0));
83	        for (int i = 1; i < letters.length() && code.length() < 4; i++) {
84	            char c = letters.charAt(i);
85	            if (c == 'H' || c == 'W') {
86	                continue;
87	            }
88	            char d = digit(c);
89	            if (d != '0' && d != previous) {
90	                code.append(d);
91	            }
92	            previous = d;
93	        }
94	        while (code.length() < 4) {
95	            code.append('0');
96	        }
97	        return code.toString();
98	    }
99	
100	    /**
101	     * The Soundex digit for a single upper-case letter, or {@code '0'} for a vowel or other letter
102	     * that carries no code.
103	     */
104	    private static char digit(char c) {
105	        switch (c) {
106	            case 'B': case 'F': case 'P': case 'V':
107	                return '1';
108	            case 'C': case 'G': case 'J': case 'K': case 'Q': case 'S': case 'X': case 'Z':
109	                return '2';
110	            case 'D': case 'T':
111	                return '3';
112	            case 'L':
113	                return '4';
114	            case 'M': case 'N':
115	                return '5';
116	            case 'R':
117	                return '6';
118	            default:
119	                return '0';
120	        }
121	    }
122	
123	    /**
124	     * The full lower-case hex SHA-256 of the UTF-8 bytes of {@code value}.
125	     *
126	     * @param value the string to hash
127	     * @return the 64-character lower-case hex digest
128	     */
129	    public static String sha256Hex(String value) {
130	        try {
131	            byte[] digest = MessageDigest.getInstance("SHA-256").digest(value.getBytes(StandardCharsets.UTF_8));
132	            StringBuilder sb = new StringBuilder(digest.length * 2);
133	            for (byte b : digest) {
134	                sb.append(String.format("%02x", b));
135	            }
136	            return sb.toString();
137	        } catch (NoSuchAlgorithmException e) {
138	            throw new IllegalStateException("SHA-256 not available", e);
139	        }
140	    }
141	}
