565	    /**
566	     * Rolls a registration date forward to a business day: any date landing on a Saturday, Sunday or
567	     * listed public holiday is advanced one day at a time until it reaches the next non-holiday
568	     * weekday, and any other weekday is returned unchanged.
569	     *
570	     * @param date the effective registration date, supplied or defaulted to the server date
571	     * @return the same date when it is a non-holiday weekday, otherwise the next non-holiday business day
572	     */
573	    private static LocalDate toBusinessDay(LocalDate date) {
574	        while (date.getDayOfWeek() == DayOfWeek.SATURDAY
575	                || date.getDayOfWeek() == DayOfWeek.SUNDAY
576	                || PUBLIC_HOLIDAYS.contains(date)) {
577	            date = date.plusDays(1);
578	        }
579	        return date;
580	    }
