582	    /**
583	     * Builds the customer code assigned to an owner on create, formatted {@code '<REGION>-<HASH8>'}
584	     * where {@code REGION} is the region code derived from the owner's postcode (the region whose
585	     * inclusive range contains the postcode, or {@code 'UNKNOWN'} when the postcode is absent or in
586	     * no known range) and {@code HASH8} is the first eight upper-cased hex characters of the SHA-256
587	     * of {@code normalizedTelephone + lastName}, e.g. {@code 'NSW-1A2B3C4D'}. There is no sequence
588	     * component: the identity is a pure region-and-hash value.
589	     *
590	     * @param postcode the postcode of the owner being created, may be {@code null}
591	     * @param normalizedTelephone the E.164 telephone of the owner being created
592	     * @param lastName the last name of the owner being created
593	     * @return the formatted customer code
594	     */
595	    private String customerCode(String postcode, String normalizedTelephone, String lastName) {
596	        return regionFromPostcode(postcode) + "-" + sha256HexPrefix(normalizedTelephone + lastName, 8);
597	    }
598	
599	    /**
600	     * The owner's current primary identifier, as carried by the structured {@link OwnerCreatedEvent}.
601	     * Today this is the {@code customerCode}; when the customerCode is later unified into the memberId
602	     * this returns the memberId instead, so the emitted event automatically carries whichever
603	     * identifier is primary at the time of the create.
604	     *
605	     * @param owner the owner just created
606	     * @return the owner's primary identifier
607	     */
608	    private String primaryIdentifier(Owner owner) {
609	        return owner.getCustomerCode();
610	    }
611	
612	    /**
613	     * De-duplicates a freshly computed customer code against the customer codes already held by
614	     * existing owners. When the code is unused it is returned unchanged; otherwise {@code '-<n>'} is
615	     * appended with the smallest {@code n} of 2 or more that yields a code no existing owner carries.
616	     *
617	     * @param customerCode the computed customer code for the owner being created
618	     * @return the same code when unique, otherwise the code with a {@code '-<n>'} suffix that makes
619	     *     it unique
620	     */
621	    private String deduplicateCustomerCode(String customerCode) {
622	        Set<String> existing = new java.util.HashSet<>();
623	        for (Owner owner : this.clinicService.findAllOwners()) {
624	            if (owner.getCustomerCode() != null) {
625	                existing.add(owner.getCustomerCode());
626	            }
627	        }
628	        if (!existing.contains(customerCode)) {
629	            return customerCode;
630	        }
631	        int n = 2;
632	        while (existing.contains(customerCode + "-" + n)) {
633	            n++;
634	        }
635	        return customerCode + "-" + n;
636	    }
