638	    /**
639	     * Returns the region code whose inclusive postcode range contains the given 4-digit postcode
640	     * (NSW 2000-2099, VIC 3000-3099, QLD 4000-4099), or {@code 'UNKNOWN'} when the postcode is
641	     * {@code null}, non-numeric, or in no known range.
642	     *
643	     * @param postcode the postcode, may be {@code null}
644	     * @return the region code, or {@code 'UNKNOWN'}
645	     */
646	    private static String regionFromPostcode(String postcode) {
647	        if (postcode == null || postcode.isBlank()) {
648	            return "UNKNOWN";
649	        }
650	        int code;
651	        try {
652	            code = Integer.parseInt(postcode.trim());
653	        } catch (NumberFormatException e) {
654	            return "UNKNOWN";
655	        }
656	        for (java.util.Map.Entry<String, int[]> entry : REGION_POSTCODES.entrySet()) {
657	            int[] range = entry.getValue();
658	            if (code >= range[0] && code <= range[1]) {
659	                return entry.getKey();
660	            }
661	        }
662	        return "UNKNOWN";
663	    }
664	
665	    /**
666	     * Computes the SHA-256 of {@code value} and returns its first {@code length} hex characters,
667	     * upper-cased.
668	     *
669	     * @param value the string to hash
670	     * @param length the number of leading hex characters to return
671	     * @return the upper-cased hex prefix of the digest
672	     */
673	    private static String sha256HexPrefix(String value, int length) {
674	        try {
675	            byte[] digest = MessageDigest.getInstance("SHA-256").digest(value.getBytes(StandardCharsets.UTF_8));
676	            StringBuilder sb = new StringBuilder(digest.length * 2);
677	            for (byte b : digest) {
678	                sb.append(String.format("%02x", b));
679	            }
680	            return sb.substring(0, length).toUpperCase(Locale.ROOT);
681	        } catch (NoSuchAlgorithmException e) {
682	            throw new IllegalStateException("SHA-256 not available", e);
683	        }
684	    }
