686	    /**
687	     * Counts the existing owners that share the owner-to-be's first and last name, compared
688	     * case-insensitively (surrounding whitespace trimmed). The count reflects the state before the
689	     * new owner is persisted, so it excludes the owner being created.
690	     *
691	     * @param firstName the first name of the owner being created
692	     * @param lastName the last name of the owner being created
693	     * @return the number of existing owners with the same first and last name
694	     */
695	    private int countNamesakes(String firstName, String lastName) {
696	        String normalizedFirstName = normalizeName(firstName);
697	        String normalizedLastName = normalizeName(lastName);
698	        return (int) this.clinicService.findAllOwners().stream()
699	            .filter(existing ->
700	                normalizedFirstName.equals(normalizeName(existing.getFirstName()))
701	                    && normalizedLastName.equals(normalizeName(existing.getLastName())))
702	            .count();
703	    }
