705	    /**
706	     * Counts the members of the owner-to-be's household after this create, i.e. one more than the
707	     * number of existing owners already carrying the same {@code householdId}. The household
708	     * identifier is a deterministic function of last name and postcode, so a solo owner (the only one
709	     * with that identifier) is a household of one. The count includes the owner being created (hence
710	     * the {@code + 1}).
711	     *
712	     * @param householdId the stable household identifier of the owner being created
713	     * @return the number of household members after this create (always at least 1)
714	     */
715	    private int householdSize(String householdId) {
716	        if (householdId == null) {
717	            return 1;
718	        }
719	        return (int) this.clinicService.findAllOwners().stream()
720	            .filter(existing -> householdId.equals(existing.getHouseholdId()))
721	            .count() + 1;
722	    }
723	
724	    /**
725	     * Computes the household-capped membership level for the owner being created. The level starts as
726	     * the owner's own derived level (from its membership points). When at least one existing (active)
727	     * household member shares the owner's {@code householdId}, the level is capped so it may not exceed
728	     * one above the current maximum membership level among those existing members; with no existing
729	     * household member no cap applies and the derived level is returned unchanged. Returns {@code null}
730	     * when no level can be derived for the owner.
731	     *
732	     * @param owner the owner being created, with its level-affecting fields already populated
733	     * @param householdId the stable household identifier of the owner being created
734	     * @return the capped membership level, or {@code null} when none can be derived
735	     */
736	    private Integer cappedMembershipLevel(Owner owner, String householdId) {
737	        Integer level = ownerMapper.membershipLevel(owner);
738	        if (level == null || householdId == null) {
739	            return level;
740	        }
741	        java.util.OptionalInt maxExisting = activeOwners()
742	            .filter(existing -> householdId.equals(existing.getHouseholdId()))
743	            .map(ownerMapper::membershipLevel)
744	            .filter(java.util.Objects::nonNull)
745	            .mapToInt(Integer::intValue)
746	            .max();
747	        if (maxExisting.isPresent()) {
748	            level = Math.min(level, maxExisting.getAsInt() + 1);
749	        }
750	        return level;
751	    }
