764	    /**
765	     * The fixed city-to-region table used to validate a postcode against its city
766	     * (Sydney->NSW, Melbourne->VIC, Brisbane->QLD). A city not in this table has no known region and
767	     * therefore accepts any 4-digit postcode.
768	     */
769	    private static final java.util.Map<String, String> CITY_REGION = java.util.Map.of(
770	        "Sydney", "NSW", "Melbourne", "VIC", "Brisbane", "QLD");
771	
772	    /**
773	     * The fixed region-to-postcode-range table: each region admits an inclusive 4-digit range
774	     * (NSW 2000-2099, VIC 3000-3099, QLD 4000-4099).
775	     */
776	    private static final java.util.Map<String, int[]> REGION_POSTCODES = java.util.Map.of(
777	        "NSW", new int[] {2000, 2099}, "VIC", new int[] {3000, 3099}, "QLD", new int[] {4000, 4099});
778	
779	    /**
780	     * Validates an owner's optional postcode on create. A {@code null} or blank postcode is left
781	     * untouched (postcode is optional when absent). When present it must be exactly four digits and,
782	     * when the city maps to a known region, must fall within that region's inclusive range
783	     * (NSW 2000-2099, VIC 3000-3099, QLD 4000-4099). A city with no known region accepts any 4-digit
784	     * postcode.
785	     *
786	     * @param city the city of the owner being created
787	     * @param postcode the raw postcode as supplied by the caller, may be {@code null}
788	     * @throws InvalidPostcodeException if a present postcode is not four digits or is out of range
789	     *     for the city's region
790	     */
791	    private static void validatePostcode(String city, String postcode) {
792	        if (postcode == null || postcode.isBlank()) {
793	            return;
794	        }
795	        if (!postcode.matches("\\d{4}")) {
796	            throw new InvalidPostcodeException("Postcode must be exactly 4 digits");
797	        }
798	        String region = CITY_REGION.get(city);
799	        int[] range = region == null ? null : REGION_POSTCODES.get(region);
800	        if (range != null) {
801	            int value = Integer.parseInt(postcode);
802	            if (value < range[0] || value > range[1]) {
803	                throw new InvalidPostcodeException(
804	                    "Postcode is out of range for the city's region");
805	            }
806	        }
807	    }
